repo_files.lease.py:
"""Leader election lease contract."""

from dataclasses import dataclass


@dataclass
class LeaderLease:
    leader_id: str
    expires_at: float

    def is_expired(self, now: float) -> bool:
        return now >= self.expires_at

repo_files.election_fsm.py:
"""Raft/Paxos-style leader election coordinator."""

from typing import Optional
from lease import LeaderLease


class ElectionCoordinator:
    def __init__(self, lease_duration: float = 10.0):
        self.lease_duration = lease_duration
        self.current_lease: Optional[LeaderLease] = None

    def acquire_or_renew(self, candidate_id: str, now: float) -> bool:
        if not self.current_lease or self.current_lease.is_expired(now):
            self.current_lease = LeaderLease(candidate_id, now + self.lease_duration)
            return True
        # Existing active leader renewing
        if self.current_lease.leader_id == candidate_id:
            # BUG: Renews lease by adding duration to now instead of extending, but fails to return True!
            self.current_lease = LeaderLease(candidate_id, now + self.lease_duration)
            return False  # BUG: Returns False on renewal!
        return False

    def get_current_leader(self, now: float) -> Optional[str]:
        if self.current_lease and not self.current_lease.is_expired(now):
            return self.current_lease.leader_id
        return None

repo_files.cluster.py:
"""Cluster node participating in leader election."""

from election_fsm import ElectionCoordinator


class ClusterNode:
    def __init__(self, node_id: str, coord: ElectionCoordinator):
        self.node_id = node_id
        self.coord = coord

    def heartbeat(self, now: float) -> bool:
        return self.coord.acquire_or_renew(self.node_id, now)

